/*
 * Al Bahar Journey Desk — bespoke V2 proof of concept.
 * Static GitHub Pages demo. All customer data lives in browser storage only.
 * One adaptive customer PDF template; the 'masters' are reusable itinerary content,
 * not separate layouts. No AI, no live booking inventory, no invented confirmations.
 */
(()=>{'use strict';
const KEY='albahar-journey-desk-v2', OLD='albahar-itinerary-studio-v1', GOOGLE_KEY='albahar-google-places-browser-key';
// Local persistence on GitHub Pages, with an in-memory fallback for restricted browsers.
const storage=(()=>{try{const s=window.localStorage;s.setItem('__albahar_test','1');s.removeItem('__albahar_test');return s;}catch(e){const m=new Map();return {getItem:k=>m.get(k)||null,setItem:(k,v)=>m.set(k,String(v)),removeItem:k=>m.delete(k)};}})();
const IMAGE_BASE='assets/destinations/';
const DESTS={
 kashmir:{name:'Kashmir',aliases:['kashmir','srinagar','gulmarg','pahalgam','sonamarg'],imgs:['signature.webp','panorama.webp','close-up.webp']},
 kerala:{name:'Kerala',aliases:['kerala','kochi','cochin','munnar','alappuzha','alleppey','thekkady'],imgs:['signature.webp','panorama.webp','close-up.webp']},
 dubai:{name:'Dubai',aliases:['dubai','abu dhabi','united arab emirates','uae'],imgs:['signature.webp','panorama.webp','close-up.webp']},
 bali:{name:'Bali',aliases:['bali','indonesia','ubud','uluwatu'],imgs:['signature.webp','panorama.webp','close-up.webp']}
};
const SERVICE_KINDS=['Activity','Transfer','Hotel','Meal','Flight','Other'];
const STUB='This itinerary is a proposed travel plan. All services, timings, tickets, transfers and hotel arrangements are subject to availability and final confirmation. Only inclusions expressly listed are part of the proposed arrangement.';
const $=(q,root=document)=>root.querySelector(q);const $$=(q,root=document)=>[...root.querySelectorAll(q)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const a=esc;const uid=()=>Math.random().toString(36).slice(2,10);const clone=x=>JSON.parse(JSON.stringify(x));
const iso=(d)=>{if(!(d instanceof Date)||isNaN(d))return '';const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),da=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${da}`};
const fromISO=s=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(String(s||'')))return null;const [y,m,d]=s.split('-').map(Number);const r=new Date(y,m-1,d,12);return r.getFullYear()===y&&r.getMonth()===m-1&&r.getDate()===d?r:null};
const plus=(date,n)=>{const d=fromISO(date);if(!d)return '';d.setDate(d.getDate()+n);return iso(d)};
const daysBetween=(x,y)=>{const a=fromISO(x),b=fromISO(y);if(!a||!b)return 0;return Math.round((b-a)/86400000)+1};
const dateLabel=d=>{const x=fromISO(d);return x?x.toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'Date to confirm'};
const shortDate=d=>{const x=fromISO(d);return x?x.toLocaleDateString('en-IN',{day:'numeric',month:'short'}):'TBC'};
const norm=s=>String(s||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
function destKey(place){const n=norm(place);return Object.keys(DESTS).find(k=>n===k||DESTS[k].aliases.some(v=>n===v||n.startsWith(v+' ')||n.endsWith(' '+v)||n.includes(' '+v+' ')))||'';}
const imagesFor=place=>{const key=destKey(place);return key?DESTS[key].imgs.map((name,i)=>({src:`${IMAGE_BASE}${key}/${name}`,name:['Signature','Wide frame','Close study'][i]})):[]};
const dDay=(title='',events=[])=>({id:uid(),title,overview:'',meals:[],events:events.map(x=>({id:uid(),time:'',kind:'Activity',note:'',...typeof x==='string'?{name:x}:x})),overnight:''});
const DEFAULT_MASTERS=[
 {id:'builtin-kashmir',name:'Kashmir · Scenic Escape',destination:'Kashmir',subtitle:'5 days / landscape & leisure',builtIn:true,days:[dDay('Arrival in Srinagar',[{name:'Arrival transfer',kind:'Transfer'},'Hotel check-in','Evening by Dal Lake']),dDay('Gulmarg countryside',['Drive to Gulmarg','Scenic sightseeing and leisure','Return to Srinagar']),dDay('Pahalgam excursion',['Drive to Pahalgam','Valley sightseeing','Return to hotel']),dDay('Srinagar at leisure',['Local sightseeing','Shopping or leisure time']),dDay('Departure',[{name:'Hotel checkout',kind:'Hotel'},{name:'Airport transfer',kind:'Transfer'}])]},
 {id:'builtin-kerala',name:'Kerala · Backwater Trail',destination:'Kerala',subtitle:'5 days / nature & backwaters',builtIn:true,days:[dDay('Welcome to Kochi',[{name:'Arrival transfer',kind:'Transfer'},'Check-in and time at leisure']),dDay('The hills of Munnar',['Scenic drive to Munnar','Tea estate visit']),dDay('Munnar discoveries',['Local sightseeing','Optional nature experience']),dDay('Alleppey backwaters',['Travel to Alleppey','Backwater experience']),dDay('Departure',[{name:'Checkout',kind:'Hotel'},{name:'Departure transfer',kind:'Transfer'}])]},
 {id:'builtin-dubai',name:'Dubai · City Essentials',destination:'Dubai',subtitle:'5 days / city & desert',builtIn:true,days:[dDay('Arrival in Dubai',[{name:'Airport pickup',kind:'Transfer'},'Hotel check-in']),dDay('Dubai highlights',['City orientation tour','Evening at leisure']),dDay('Abu Dhabi excursion',['Full-day sightseeing excursion']),dDay('Desert experiences',['Desert safari experience','Evening dinner (if included)']),dDay('Departure',[{name:'Hotel checkout',kind:'Hotel'},{name:'Airport transfer',kind:'Transfer'}])]},
 {id:'builtin-flex',name:'Flexible · Any Destination',destination:'',subtitle:'4 days / blank structure',builtIn:true,days:[dDay('Arrival & settle in',[{name:'Arrival transfer',kind:'Transfer'}]),dDay('Discover the destination',[]),dDay('Experience & explore',[]),dDay('Departure',[{name:'Departure transfer',kind:'Transfer'}])]}
];
function blank(start='2026-11-12') {return {id:uid(),reference:'AB-'+String(Date.now()).slice(-6),customer:'',destination:'',title:'',startDate:start,endDate:plus(start,4),adults:2,children:0,rooms:0,cover:'',nights:'',notes:'',included:'',excluded:'',stays:[],days:[dDay('Arrival'),dDay('Discover'),dDay('Explore'),dDay('At leisure'),dDay('Departure')],createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};}
function seeded(){const t=blank('2026-11-12');applyMasterTo(t,DEFAULT_MASTERS[0]);t.customer='Demo Traveller';t.title='Kashmir, at your own pace';t.adults=2;t.rooms=0;return t;}
function applyMasterTo(t,m){t.destination=m.destination||t.destination;t.days=clone(m.days).map(d=>({...d,id:uid(),events:(d.events||[]).map(e=>({...e,id:uid()}))}));t.endDate=plus(t.startDate,t.days.length-1);t.cover='';t.title=`${t.destination||'Your'} journey`;
// Reuse saved stay structures without pretending old check-in dates are confirmed.
t.stays=(m.stays||[]).map(h=>({...clone(h),id:uid(),checkIn:t.startDate,checkOut:t.endDate}));
t.included='';t.excluded='';t.notes='';t.rooms=0;}
function getCover(t){if(t.cover==='none')return '';if(t.cover?.startsWith('data:image/'))return t.cover;return imagesFor(t.destination).some(x=>x.src===t.cover)?t.cover:(imagesFor(t.destination)[0]?.src||'');}
function normalizeTrip(raw){if(!raw||typeof raw!=='object')return null;const b=blank();for(const k of ['id','reference','customer','destination','title','startDate','endDate','cover','notes','included','excluded','createdAt','updatedAt'])if(typeof raw[k]==='string')b[k]=raw[k];for(const k of ['adults','children','rooms'])if(Number.isFinite(+raw[k]))b[k]=Math.max(0,Math.min(250,Number(raw[k])));b.days=Array.isArray(raw.days)?raw.days.slice(0,45).map(d=>({id:String(d.id||uid()),title:String(d.title||''),overview:String(d.overview||''),overnight:String(d.overnight||''),meals:Array.isArray(d.meals)?d.meals.filter(x=>['Breakfast','Lunch','Dinner'].includes(x)):[],events:Array.isArray(d.events)?d.events.slice(0,50).map(e=>({id:String(e.id||uid()),name:String(e.name||''),kind:SERVICE_KINDS.includes(e.kind)?e.kind:'Activity',time:String(e.time||''),note:String(e.note||'')})):[]})):[dDay('Arrival')];b.stays=Array.isArray(raw.stays)?raw.stays.slice(0,12).map(h=>({id:String(h.id||uid()),name:String(h.name||''),city:String(h.city||''),checkIn:String(h.checkIn||''),checkOut:String(h.checkOut||''),room:String(h.room||''),board:String(h.board||'')})):[];return b;}
function convertLegacy(x){try{const t=blank();t.customer=x.customer||'';t.title=x.tripTitle||'';t.destination=x.destination||'';t.reference=x.reference||t.reference;t.startDate=x.startDate||t.startDate;t.endDate=x.endDate||t.endDate;t.adults=+x.adults||0;t.children=+x.children||0;t.rooms=+x.rooms||1;t.cover=x.coverImage||'';t.notes=[x.arrivalInfo,x.departureInfo].filter(Boolean).join('\n');t.days=(x.days||[]).map(d=>({id:uid(),title:d.title||'',overview:d.overview||'',overnight:d.overnight||'',meals:['breakfast','lunch','dinner'].filter(meal=>String(d.meals?.[meal]||'').toLowerCase().includes('included')).map(s=>s[0].toUpperCase()+s.slice(1)),events:(d.events||[]).map(e=>({id:uid(),name:e.name||'',kind:SERVICE_KINDS.includes(e.type)?e.type:'Activity',time:e.time||'',note:[e.description,e.transfer,e.tickets,e.notes].filter(Boolean).join(' · ')}))}));if(!t.days.length)t.days=[dDay('Arrival')];if(x.hotel?.name)t.stays=[{id:uid(),name:x.hotel.name,city:x.hotel.address||'',checkIn:x.hotel.checkIn||t.startDate,checkOut:x.hotel.checkOut||t.endDate,room:x.hotel.roomType||'',board:x.hotel.board||''}];return t;}catch(e){return null;}}
let model={trips:[],activeId:'',masters:[],agency:{name:'Al Bahar Tours & Travels',tagline:'Discover the World with Us!',phone:'',email:'',website:'',staffName:'',staffRole:'Travel Consultant',staffPhone:'',staffEmail:'',logo:'assets/al-bahar-logo.png'},settings:{},migrated:false};
let ui={view:'workspace',dayOpen:0,previewMobile:false,googleOpen:false,search:''};let isSaving=false;
function load(){try{const obj=JSON.parse(storage.getItem(KEY)||'null');if(obj?.trips?.length){model={...model,...obj,trips:obj.trips.map(normalizeTrip).filter(Boolean)};if(!model.trips.length)throw Error('No valid trips');if(!model.trips.some(t=>t.id===model.activeId))model.activeId=model.trips[0].id;model.masters=(model.masters||[]).filter(Boolean);return;}}catch(e){console.warn('Could not load saved data',e)}const s=seeded();model.trips=[s];model.activeId=s.id; // Import previous V1.3 drafts without deleting the original data.
 try{const legacy=JSON.parse(storage.getItem(OLD)||'null');if(legacy?.trips?.length){const trips=legacy.trips.slice(0,30).map(convertLegacy).filter(Boolean);model.trips.push(...trips);model.migrated=true;}}catch(e){console.warn('Legacy backup unavailable',e)}save();}
const current=()=>model.trips.find(t=>t.id===model.activeId)||model.trips[0];
function save(){if(isSaving)return;const x=JSON.stringify(model);try{storage.setItem(KEY,x);const s=$('#saveState');if(s)s.innerHTML='●&nbsp; Saved on this device';}catch(e){const s=$('#saveState');if(s)s.textContent='Storage full — export a backup';toast('Browser storage is full. Export your itinerary before leaving.');}}
function toast(message){const node=$('#toast');node.textContent=message;node.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.classList.remove('show'),4000);}
function field(label,key,value,type='text',extra=''){return `<label class="field"><span>${esc(label)}</span>${type==='textarea'?`<textarea data-bind="${a(key)}" ${extra}>${esc(value)}</textarea>`:`<input data-bind="${a(key)}" type="${a(type)}" value="${a(value)}" ${extra}>`}</label>`;}
function select(label,key,value,options){return `<label class="field"><span>${esc(label)}</span><select data-bind="${a(key)}">${options.map(o=>`<option value="${a(o)}" ${String(o)===String(value)?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;}
function selectedMetric(t){const n=daysBetween(t.startDate,t.endDate);return n>0?`${n} days · ${n-1} nights`:`${t.days.length} days`}
function currentHotel(date){const t=current();return t.stays.find(h=>date>=h.checkIn&&date<h.checkOut)?.name||'';}
function brief(){const t=current();return `<section class="panel panel-pad" id="brief"><div class="panel-header"><h2>Journey brief</h2><span class="tiny-label">01 / CLIENT & DATES</span></div><div class="field-grid">${field('Prepared for','customer',t.customer,'text','placeholder="Customer or family name"')}${field('Destination','destination',t.destination,'text','placeholder="e.g. Kashmir, Dubai, Kerala"')}${field('Departure date','startDate',t.startDate,'date')}${field('Return date','endDate',t.endDate,'date')}</div><div class="brief-footer"><span class="brief-meta"><b>${esc(selectedMetric(t))}</b> &nbsp;·&nbsp; Reference ${esc(t.reference)}</span><button class="inline-link" data-act="edit-cover">Cover & trip details ↗</button></div></section>`;}
function starter(){const t=current();return `<section class="panel panel-pad"><div class="panel-header"><h2>Start from a proven structure</h2><span class="tiny-label">REUSE THE WORK</span></div><div class="starter-row">${allMasters().slice(0,8).map(m=>`<button class="starter-chip" data-act="apply-master" data-id="${a(m.id)}">${esc(m.name)}</button>`).join('')}</div><div class="template-note"><span style="font-size:16px;color:#b48b5e">✦</span><span>Templates are editable planning structures, not bookings. Change activities, hotels and inclusions for each client.</span></div></section>`;}
function dayRow(t,d,n){const isOpen=ui.dayOpen===n,dt=plus(t.startDate,n);return `<article class="day-row" data-day="${n}"><div class="day-main" data-act="toggle-day" data-n="${n}" role="button" tabindex="0" aria-expanded="${isOpen}"><div class="day-num"><strong>${String(n+1).padStart(2,'0')}</strong><span>DAY</span></div><div class="day-content"><h3>${esc(d.title||'Untitled day')}</h3><div class="day-desc">${esc(shortDate(dt))} &nbsp;·&nbsp; ${d.events.length} services ${d.meals.length?' · '+d.meals.join(' / '):''}</div></div><div class="day-opts"><button class="square-btn" title="Copy day" data-act="duplicate-day" data-n="${n}">⧉</button><button class="square-btn" title="Delete day" data-act="remove-day" data-n="${n}">×</button><span style="font-size:13px;color:#98a4ad;margin-left:4px">${isOpen?'−':'+'}</span></div></div>${isOpen?expandedDay(d,n):''}</article>`;}
function expandedDay(d,n){return `<div class="day-expanded"><div class="field-grid">${field('Day heading',`days.${n}.title`,d.title,'text','placeholder="e.g. The hills of Gulmarg"')}${field('Short introduction (optional)',`days.${n}.overview`,d.overview,'text','placeholder="Add a short day description"')}</div><div class="event-list">${d.events.map((e,i)=>eventRow(e,n,i)).join('')}</div><div class="day-expand-actions"><button class="btn small" data-act="add-event" data-n="${n}">+ Add an activity</button><button class="btn textual small" data-act="add-many" data-n="${n}">Paste several activities</button></div><div class="day-meals"><span style="font-size:10px;font-weight:700;color:#7a878e;margin-right:4px">CONFIRMED MEALS</span>${['Breakfast','Lunch','Dinner'].map(meal=>`<button class="meal-toggle ${d.meals.includes(meal)?'selected':''}" data-act="meal" data-n="${n}" data-meal="${meal}">${d.meals.includes(meal)?'✓ ':''}${meal}</button>`).join('')}</div></div>`;}
function eventRow(e,n,i){return `<div class="event-line"><input aria-label="Service time" placeholder="Time / TBC" data-bind="days.${n}.events.${i}.time" value="${a(e.time)}"><input aria-label="Service name" placeholder="Activity / transfer / meal" data-bind="days.${n}.events.${i}.name" value="${a(e.name)}"><select aria-label="Service category" data-bind="days.${n}.events.${i}.kind">${SERVICE_KINDS.map(k=>`<option ${e.kind===k?'selected':''}>${k}</option>`).join('')}</select><button class="square-btn danger" title="Remove activity" data-act="remove-event" data-n="${n}" data-e="${i}">×</button><input class="event-note" aria-label="Optional activity note" data-bind="days.${n}.events.${i}.note" placeholder="Optional details: transfer, inclusions, tickets..." value="${a(e.note)}"></div>`;}
function board(){const t=current();return `<section class="panel panel-pad"><div class="section-head"><div><span class="eyebrow">02 / THE ITINERARY</span><h2 style="margin-top:7px">Day-by-day route</h2><p class="subtle">Edit only what's different. Each line becomes part of the customer PDF.</p></div><button class="btn small" data-act="paste-outline">Paste a full plan ↗</button></div><div class="day-list">${t.days.map((d,i)=>dayRow(t,d,i)).join('')}</div><div class="add-day-row"><button class="btn textual" data-act="add-day">+ Add another day</button></div></section>`;}
function stays(){const t=current();return `<section class="panel panel-pad"><div class="panel-header"><h2>Accommodation</h2><span class="tiny-label">OPTIONAL / NO PHOTOS</span></div>${t.stays.length?`<div class="stay-list">${t.stays.map((h,i)=>`<div class="stay-row"><div><strong>${esc(h.name||'Unnamed stay')}</strong><p>${esc(h.city||'Location to confirm')} · ${esc(shortDate(h.checkIn))} – ${esc(shortDate(h.checkOut))}${h.room?' · '+esc(h.room):''}</p></div><div class="stay-actions"><button class="btn small" data-act="edit-stay" data-n="${i}">Edit</button><button class="btn small" data-act="remove-stay" data-n="${i}" aria-label="Delete stay">×</button></div></div>`).join('')}</div>`:`<div class="no-photo-note">Hotel details are optional. If no hotel is confirmed, the PDF omits the stay panel entirely — no empty image frames or placeholder content.</div>`}<div style="margin-top:15px"><button class="btn small" data-act="add-stay">+ Add hotel / stay</button></div></section>`;}
function inclusions(){const t=current();return `<section class="panel panel-pad"><div class="panel-header"><h2>Proposal details</h2><span class="tiny-label">ADD ONLY IF NEEDED</span></div><details><summary class="subtle" style="cursor:pointer;font-weight:700">Inclusions, exclusions & important notes</summary><div class="field-grid" style="margin-top:18px">${field('Inclusions (one per line)','included',t.included,'textarea','placeholder="Airport transfers&#10;Breakfast"')}${field('Exclusions (one per line)','excluded',t.excluded,'textarea','placeholder="Airfare&#10;Personal expenses"')}${field('Special notes','notes',t.notes,'textarea','class="wide" placeholder="Any important travel details or conditions"')}</div></details><p class="small-note" style="margin-top:12px">The document never invents tickets, meals, hotel reservations or other services. Employees confirm the actual package inclusions.</p></section>`;}
function miniPreview(){const t=current(),src=getCover(t),n=t.days.length;return `<div class="preview-column" id="previewColumn"><div class="preview-cap"><span>LIVE PROPOSAL / COVER</span><span>A4 DOCUMENT</span></div><div class="doc-preview"><div class="doc-sheet"><div class="mini-cover-img" style="${src?`background-image:url('${a(src)}')`:'background:#25394c'}"></div><div class="mini-cover-body"><div class="mini-rule"></div><span class="mini-meta">AN AL BAHAR JOURNEY / ${esc(t.reference)}</span><div class="mini-title">${esc(t.title||'A journey to '+(t.destination||'somewhere remarkable'))}</div><div class="mini-meta">PREPARED FOR ${esc(t.customer||'YOUR TRAVELLER')}</div><div class="mini-stats"><div><b>${n}</b><span>Days</span></div><div><b>${Math.max(0,n-1)}</b><span>Nights</span></div><div><b>${t.adults+t.children}</b><span>Travellers</span></div></div></div></div></div><div class="preview-bottom"><span>Cover adapts to destination</span><span>Document · ${n} days</span></div><div class="preview-actions"><button class="btn" data-act="preview-full">View pages</button><button class="btn dark" data-act="print-pdf">Export PDF ↗</button></div></div>`;}
function workspace(){const t=current();return `<div class="screen-pad"><div class="page-intro"><div><div class="page-breadcrumb">JOURNEY DESK / CURRENT PROPOSAL</div><h1>Plan the trip.<br><em style="font-weight:400;color:#b27a48">Leave the paperwork.</em></h1><p>One signature Al Bahar layout. Start from a master route, personalise the journey, and deliver a customer-ready PDF — without filling dozens of boxes.</p></div><button class="btn dark" data-act="new-trip">+ New journey</button></div>${model.migrated?`<div class="no-photo-note" style="margin-bottom:20px">Your older V1.3 browser drafts were copied into Saved journeys. The originals remain untouched. Back up important customer data before making changes.</div>`:''}<div class="work-grid ${ui.previewMobile?'mobile-preview':''}"><div class="stack">${brief()}${starter()}${board()}${stays()}${inclusions()}<div class="action-row"><button class="btn rose large" data-act="print-pdf">Export customer itinerary ↗</button><button class="btn" data-act="save-master">Save as reusable master</button><button class="btn quiet" data-act="duplicate-trip">Duplicate for next customer</button></div><div class="small-note">Customer information is stored only on this browser in this demo. No staff logins, central database or live confirmations.</div></div>${miniPreview()}</div><div class="mobile-bottom"><button data-act="mobile-edit" class="${ui.previewMobile?'':'active'}">Edit journey</button><button data-act="mobile-preview" class="${ui.previewMobile?'active':''}">Live preview</button></div></div>`;}
function allMasters(){return [...DEFAULT_MASTERS,...model.masters];}
function templatesScreen(){return `<div class="screen-pad"><div class="page-intro"><div><div class="page-breadcrumb">YOUR AGENCY / REUSABLE CONTENT</div><h1>One format.<br>Countless journeys.</h1><p>Keep approved route structures once; copy them for future enquiries. The customer PDF automatically adapts to every destination.</p></div><button class="btn dark" data-act="save-master">+ Save current route</button></div><div class="library-grid">${allMasters().map(m=>`<article class="master-card"><div><div class="master-color"></div><span class="tiny-label">${m.builtIn?'STARTER STRUCTURE':'SAVED BY YOUR TEAM'}</span><h3>${esc(m.name)}</h3><p>${esc(m.subtitle||`${m.days.length} days · ${m.destination||'Any destination'}`)}</p></div><div class="card-actions"><button class="btn dark small" data-act="use-master-new" data-id="${a(m.id)}">Create journey ↗</button>${!m.builtIn?`<button class="btn small danger" data-act="delete-master" data-id="${a(m.id)}">Delete</button>`:''}</div></article>`).join('')}</div><p class="small-note" style="margin-top:20px">Starter structures are illustrative ideas, not confirmed bookings. Saved masters retain the itinerary route and optional hotel structure, not customer details.</p></div>`;}
function tripScreen(){const query=norm(ui.search),arr=model.trips.filter(t=>!query||norm([t.customer,t.destination,t.reference,t.title].join(' ')).includes(query));return `<div class="screen-pad"><div class="page-intro"><div><div class="page-breadcrumb">JOURNEY DESK / PRIVATE DRAFTS</div><h1>Your itineraries.</h1><p>Pick up an enquiry, duplicate a successful route or create something new. All saved journeys are local to this browser.</p></div><button class="btn dark" data-act="new-trip">+ New journey</button></div><div class="panel panel-pad" style="margin-bottom:18px;max-width:650px">${field('Find by traveller, destination or reference','_search',ui.search,'text','placeholder="Search saved journeys"')}</div><div class="library-grid">${arr.map(t=>`<article class="trip-card"><div><span class="tiny-label">${esc(t.reference)}</span><h3>${esc(t.title||t.destination||'Untitled journey')}</h3><p>${esc(t.customer||'Customer not set')}<br>${esc(shortDate(t.startDate))} – ${esc(shortDate(t.endDate))} · ${t.days.length} days</p></div><div class="card-actions"><button class="btn dark small" data-act="open-trip" data-id="${a(t.id)}">Open ↗</button><button class="btn small" data-act="duplicate-selected" data-id="${a(t.id)}">Duplicate</button><button class="btn small danger" data-act="delete-trip" data-id="${a(t.id)}">Delete</button></div></article>`).join('')}</div>${!arr.length?`<div class="empty-state"><h3>No matching journeys</h3><p>Try a different search or create a new one.</p></div>`:''}<div class="action-row" style="margin-top:25px"><button class="btn" data-act="backup-all">Download backup JSON</button><button class="btn" data-act="import-json">Import JSON / V1.3 backup</button></div></div>`;}
function agencyScreen(){const g=model.agency;return `<div class="screen-pad"><div class="page-intro"><div><div class="page-breadcrumb">AL BAHAR / OFFICE SETTINGS</div><h1>Set it once.<br>Use it every time.</h1><p>Your agency identity and consultant contact appear automatically in every new customer itinerary.</p></div></div><div class="work-grid"><div class="stack"><section class="panel panel-pad"><div class="panel-header"><h2>Agency identity</h2><span class="tiny-label">SAVED ON THIS DEVICE</span></div><img class="agency-logo" src="${a(g.logo)}" alt="Al Bahar logo"><div class="field-grid" style="margin-top:18px">${field('Business name','agency.name',g.name)}${field('Tagline','agency.tagline',g.tagline)}${field('Business phone','agency.phone',g.phone)}${field('Business email','agency.email',g.email,'email')}${field('Website','agency.website',g.website)}</div></section><section class="panel panel-pad"><div class="panel-header"><h2>Prepared by</h2><span class="tiny-label">REUSED ON EVERY PDF</span></div><div class="field-grid">${field('Employee name','agency.staffName',g.staffName,'text','placeholder="Enter once"')}${field('Role','agency.staffRole',g.staffRole)}${field('Phone number','agency.staffPhone',g.staffPhone)}${field('Email','agency.staffEmail',g.staffEmail,'email')}</div><p class="small-note">This demo has no employee authentication; a production CRM would pull the consultant from the authenticated staff profile.</p></section><section class="panel panel-pad"><div class="panel-header"><h2>Google hotel autocomplete</h2><span class="tiny-label">OPTIONAL</span></div><p class="small-note">Only hotel name and address are retrieved. Requires a website-restricted Google Maps browser API key and billing-enabled Google Cloud project. No prices, room confirmation or hotel photos.</p>${field('Restricted browser API key','_googleKey',storage.getItem(GOOGLE_KEY)||'','password','autocomplete="off" placeholder="Optional"')}<div class="action-row" style="margin-top:12px"><button class="btn small dark" data-act="save-key">Save key on this device</button><button class="btn small danger" data-act="clear-key">Remove key</button></div></section><div class="action-row"><button class="btn" data-act="backup-all">Download all journeys & masters</button><button class="btn" data-act="import-json">Import a backup</button></div></div><aside><div class="no-photo-note"><strong>Important for the demo:</strong><p>GitHub Pages is a public, static site. It does not supply shared employee logins or protected customer storage. Do not add passport scans, personal identity documents or payment information.</p></div></aside></div></div>`;}
function render(){const r=$('#screen');if(!r)return;$('#crumbView').textContent=({workspace:'ITINERARY DESK',trips:'SAVED JOURNEYS',masters:'MASTER TEMPLATES',agency:'AGENCY & STAFF'})[ui.view]||'JOURNEY DESK';r.innerHTML=ui.view==='workspace'?workspace():ui.view==='masters'?templatesScreen():ui.view==='trips'?tripScreen():agencyScreen();$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===ui.view));$('#navTripCount').textContent=model.trips.length;}
function previewBrief(){if(ui.view==='workspace'){const stage=$('#previewColumn');if(stage)stage.outerHTML=miniPreview();}}
function getPath(object,path){return path.split('.').reduce((o,key)=>o?.[key],object)}
function setPath(object,path,value){const keys=path.split('.');let o=object;for(let i=0;i<keys.length-1;i++)o=o[keys[i]];o[keys.at(-1)]=value;}
function nDaysChange(t){let n=daysBetween(t.startDate,t.endDate);if(n<1||n>45){toast('Choose a trip length from 1 to 45 days.');return}if(n>t.days.length){for(let i=t.days.length;i<n;i++)t.days.push(dDay(i===n-1?'Departure':`Day ${i+1}`));}if(n<t.days.length)t.days=t.days.slice(0,n);ui.dayOpen=Math.min(ui.dayOpen,t.days.length-1);}
function downloadJSON(name,obj){const b=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),url=URL.createObjectURL(b),link=document.createElement('a');link.href=url;link.download=name;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function modal(html){const root=$('#dialogBackdrop');root.hidden=false;$('#dialogBody').innerHTML=`<button class="dialog-close" data-act="close-dialog" aria-label="Close dialog">×</button>${html}`;$('#dialogBody').querySelector('input,textarea,button')?.focus();}
function closeModal(){const root=$('#dialogBackdrop');root.hidden=true;$('#dialogBody').innerHTML='';}
function confirmBox(title,body,ok,onYes){modal(`<div class="eyebrow">PLEASE CONFIRM</div><h2>${esc(title)}</h2><p>${esc(body)}</p><div class="dialog-buttons"><button class="btn" data-act="close-dialog">Cancel</button><button class="btn dark" id="confirmPrimary">${esc(ok)}</button></div>`);$('#confirmPrimary').addEventListener('click',()=>{closeModal();onYes()},{once:true});}
function newTrip(master=null){const t=blank(iso(new Date()));const old=current();if(master)applyMasterTo(t,master);else{t.days=[dDay('Arrival'),dDay('Day 2'),dDay('Day 3'),dDay('Departure')];t.endDate=plus(t.startDate,3);}if(old?.destination&&!master)t.destination='';model.trips.unshift(t);model.activeId=t.id;ui.view='workspace';ui.dayOpen=0;save();render();toast('New journey created. Start with your customer and destination.');}
function makeDuplicate(source){const t=clone(source);t.id=uid();t.reference='AB-'+String(Date.now()).slice(-6);t.customer='';t.createdAt=new Date().toISOString();t.updatedAt=t.createdAt;model.trips.unshift(t);model.activeId=t.id;ui.view='workspace';ui.dayOpen=0;save();render();toast('Copied the journey. Update the customer and dates.');}
function useMaster(master,inNew){if(inNew){newTrip(master);return;}confirmBox('Use this master route?','This will replace the current day plan and stays, while keeping the customer name and travel start date.','Use template',()=>{const t=current();applyMasterTo(t,master);save();render();toast('Master structure applied. Verify all activities against the customer booking.');});}
function findMaster(id){return allMasters().find(m=>m.id===id)}
function saveMaster(){const t=current();modal(`<div class="eyebrow">REUSABLE CONTENT</div><h2>Keep this journey as a master</h2><p>Only the route, stay structure and notes are saved. Future customers can start here instead of re-entering activities.</p><div class="field-grid one">${field('Template name','_masterName',t.destination?`${t.destination} · ${t.days.length}-day route`:`${t.days.length}-day route`)}</div><div class="dialog-buttons"><button class="btn" data-act="close-dialog">Cancel</button><button class="btn dark" data-act="confirm-save-master">Save master</button></div>`);}
function saveMasterNow(){const name=($('#dialogBody [data-bind="_masterName"]')?.value||'').trim();if(!name)return toast('Enter a master template name.');const t=current();model.masters.push({id:uid(),name,destination:t.destination,days:clone(t.days),stays:clone(t.stays),subtitle:`${t.days.length} days · saved by your team`,builtIn:false});save();closeModal();toast('Master saved. Find it under Master templates.');}
function addStay(index=-1){const t=current();const h=index>=0?t.stays[index]:{id:uid(),name:'',city:'',checkIn:t.startDate,checkOut:t.endDate,room:'',board:''};modal(`<div class="eyebrow">ACCOMMODATION / OPTIONAL</div><h2>${index>=0?'Edit hotel details':'Add an accommodation'}</h2><p>Only confirmed details belong in the itinerary. Hotel photographs are never required.</p><div class="field-grid">${field('Hotel / property name','_hotelName',h.name,'text','placeholder="Type a name or use Google search"')}${field('City / location','_hotelCity',h.city,'text','placeholder="City or area"')}${field('Check-in','_hotelIn',h.checkIn,'date')}${field('Check-out','_hotelOut',h.checkOut,'date')}${field('Room configuration','_hotelRoom',h.room,'text','placeholder="e.g. 2 Deluxe rooms"')}${field('Meal plan','_hotelBoard',h.board,'text','placeholder="e.g. Breakfast included"')}</div>${storage.getItem(GOOGLE_KEY)?`<div style="margin:16px 0"><button class="btn small" data-act="google-search">Find hotel via Google ↗</button><div id="googleHolder" style="margin-top:8px"></div><div class="small-note" id="googleStatus"></div></div>`:''}<div class="dialog-buttons"><button class="btn" data-act="close-dialog">Cancel</button><button class="btn dark" data-act="confirm-stay" data-n="${index}">Save accommodation</button></div>`);}
function saveStay(index){const read=k=>($(`#dialogBody [data-bind="${k}"]`)?.value||'').trim();const name=read('_hotelName');if(!name)return toast('Enter a hotel name, or cancel if none is confirmed.');const h={id:index>=0?current().stays[index].id:uid(),name,city:read('_hotelCity'),checkIn:read('_hotelIn'),checkOut:read('_hotelOut'),room:read('_hotelRoom'),board:read('_hotelBoard')};if(h.checkIn&&h.checkOut&&h.checkOut<=h.checkIn)return toast('Check-out must be after check-in.');if(index>=0)current().stays[index]=h;else current().stays.push(h);save();closeModal();render();toast('Stay saved. It will appear in the proposal.');}
function coverDialog(){const t=current(),images=imagesFor(t.destination);modal(`<div class="eyebrow">TRIP DETAILS / COVER</div><h2>The journey, your way.</h2><p>One signature document design adapts to the selected destination. Choose a local cover, upload a permitted photo, or let the typography lead.</p><div class="field-grid">${field('Proposal title','_title',t.title||'')}${field('Adults','_adults',t.adults,'number','min="0" max="250"')}${field('Children','_children',t.children,'number','min="0" max="250"')}${field('Rooms','_rooms',t.rooms,'number','min="0" max="100"')}</div>${images.length?`<div style="margin:20px 0 0"><span class="tiny-label">DESTINATION COVER COLLECTION</span><div class="image-choice-row">${images.map(im=>`<button class="image-choice ${getCover(t)===im.src?'active':''}" data-act="select-image" data-src="${a(im.src)}"><img src="${a(im.src)}" alt="${a(im.name)}"><span>${esc(im.name)}</span></button>`).join('')}</div></div>`:`<p class="small-note">No images are stored for this destination yet. You can upload your own image.</p>`}<div class="action-row" style="margin-top:16px"><button class="btn small" data-act="upload-cover">Upload your cover image</button><button class="btn small" data-act="no-cover">Text-only cover</button></div><div class="dialog-buttons"><button class="btn" data-act="close-dialog">Cancel</button><button class="btn dark" data-act="confirm-cover">Apply & close</button></div>`);}
function updateCoverData(){const read=k=>$(`#dialogBody [data-bind="${k}"]`)?.value;const t=current();t.title=read('_title')||t.title;t.adults=Math.max(0,Math.min(250,+read('_adults')||0));t.children=Math.max(0,Math.min(250,+read('_children')||0));t.rooms=Math.max(0,Math.min(100,+read('_rooms')||0));save();closeModal();render();}
function pasteDialog(day=null){modal(`<div class="eyebrow">FAST ENTRY / PASTE</div><h2>${day===null?'Paste a complete day-wise plan':'Add several activities at once'}</h2><p>${day===null?'Use “Day 1 - Arrival” headings and activity lines. The route will become editable day cards.':'Use one activity per line. Optional times like “09:00 - Airport pickup” are supported.'}</p><div class="outline-example">${day===null?'Day 1 - Arrival\n- Airport pickup\n- Check-in and evening at leisure\n\nDay 2 - Sightseeing\n- 9:00 AM - City tour\n- Local attractions': '09:00 - Airport transfer\nHotel check-in\nEvening city tour'}</div><div class="field-grid one"><label class="field"><span>PASTE HERE</span><textarea id="outlineText" rows="10" placeholder="Paste the text from a supplier or internal itinerary"></textarea></label></div><div class="dialog-buttons"><button class="btn" data-act="close-dialog">Cancel</button><button class="btn dark" data-act="apply-outline" data-n="${day===null?-1:day}">${day===null?'Build day plan':'Insert activities'}</button></div>`);}
function parseOutline(src){const lines=String(src||'').split(/\r?\n/).map(s=>s.trim()).filter(Boolean);if(lines.length>600)throw Error('Maximum 600 lines.');const days=[];let active=null;for(let x of lines){const match=x.match(/^day\s*0*(\d{1,2})\s*[.:\-–—)]?\s*(.*)$/i);if(match){const n=+match[1];if(n<1||n>45)throw Error('Days must be between 1 and 45.');active=dDay(match[2]||`Day ${n}`);days.push({n,day:active});continue;}if(!active){active=dDay('Arrival');days.push({n:1,day:active});}x=x.replace(/^(?:[•*-]|\d+[.)])\s*/,'').trim();if(!x)continue;const time=x.match(/^((?:\d{1,2}:\d{2}(?:\s*[AP]M)?|\d{1,2}\s*[AP]M))\s*[-–—:]\s*(.*)$/i);active.events.push({id:uid(),name:(time?time[2]:x).slice(0,250),kind:'Activity',time:time?time[1]:'',note:''});if(active.events.length>50)throw Error('Maximum 50 activities per day.');}
if(!days.length)throw Error('No activities found.');if(days.length>45)throw Error('Maximum 45 days.');if(days.length>1){days.forEach((d,i)=>{if(d.n!==i+1)throw Error('Day headings must be sequential starting with Day 1.');});}return days.map(x=>x.day);}
function applyOutline(n){const text=$('#outlineText')?.value||'';try{let days=parseOutline(text);const t=current();if(n<0){t.days=days;t.endDate=plus(t.startDate,days.length-1);ui.dayOpen=0;}else{t.days[n].events.push(...days.flatMap(d=>d.events));if(t.days[n].events.length>50)t.days[n].events=t.days[n].events.slice(0,50);}save();closeModal();render();toast(`${n<0?days.length+' days':days.flatMap(d=>d.events).length+' activities'} added. Confirm details before sharing.`);}catch(e){toast(e.message||'Unable to parse the outline.');}}
let googlePromise=null;
function loadGoogle(){if(window.google?.maps?.importLibrary)return Promise.resolve();if(googlePromise)return googlePromise;const key=storage.getItem(GOOGLE_KEY);if(!key)return Promise.reject(Error('No Google API key is configured.'));googlePromise=new Promise((ok,fail)=>{const callback='__albaharHotelReady';let done=false;const timer=setTimeout(()=>finish(Error('Google Places timed out.')),18000);function finish(e){if(done)return;done=true;clearTimeout(timer);delete window[callback];e?fail(e):ok();}window[callback]=()=>finish();const s=document.createElement('script');s.async=true;s.src=`https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(key)}&v=weekly&loading=async&libraries=places&callback=${callback}`;s.onerror=()=>finish(Error('Unable to connect to Google Maps.'));document.head.appendChild(s)}).catch(e=>{googlePromise=null;throw e});return googlePromise;}
async function initGoogle(){const status=$('#googleStatus'),holder=$('#googleHolder');if(!holder)return;status.textContent='Loading Google Places…';try{await loadGoogle();const {PlaceAutocompleteElement}=await google.maps.importLibrary('places');if(!$('#googleHolder'))return;const el=new PlaceAutocompleteElement();el.className='google-hotel-picker';el.setAttribute('placeholder','Search hotel by name or city');holder.replaceChildren(el);status.textContent='Choose a hotel, then confirm the selected details. Powered by Google.';el.addEventListener('gmp-select',async ev=>{try{const place=ev.placePrediction.toPlace();await place.fetchFields({fields:['displayName','formattedAddress']});const name=$('#dialogBody [data-bind="_hotelName"]'),city=$('#dialogBody [data-bind="_hotelCity"]');if(!name)return;name.value=place.displayName||'';city.value=place.formattedAddress||'';status.textContent='Hotel found. Check it matches the supplier booking before saving.';}catch(e){status.textContent='Hotel details could not be read. Enter them manually.';}});}catch(e){if(status)status.textContent=e.message||'Search unavailable. Manual entry still works.';}}
function previewFull(){const t=current();modal(`<div class="eyebrow">CUSTOMER DOCUMENT / A4</div><h2>Your personalised journey.</h2><p>The print layout uses one consistent Al Bahar design. The cover and plan are tailored to this trip.</p><div style="max-height:58vh;overflow:auto;border:1px solid #dfe3e3;padding:12px;background:#f6f6f3"><div style="background:#fff;padding:24px"><strong style="font:500 28px var(--serif)">${esc(t.title||t.destination||'Journey')}</strong><p class="small-note">${esc(t.customer||'Traveller to confirm')} · ${esc(dateLabel(t.startDate))} — ${esc(dateLabel(t.endDate))}</p>${t.days.map((d,i)=>`<div style="padding:10px 0;border-top:1px solid #e5e5e2"><b style="font-size:11px;color:#af0c5e">DAY ${i+1}</b><strong style="display:block;font:500 17px var(--serif)">${esc(d.title)}</strong><span class="small-note">${esc(d.events.map(e=>e.name).join(' · '))}</span></div>`).join('')}</div></div><div class="dialog-buttons"><button class="btn" data-act="close-dialog">Back to editor</button><button class="btn dark" data-act="print-pdf">Export PDF ↗</button></div>`);}
function pLogo(){return `<img src="${a(model.agency.logo)}" alt="Al Bahar Tours & Travels">`;}
function pMast(title){return `<div class="p-mast">${pLogo()}<small>AL BAHAR / ${esc(title)}</small></div>`;}
function lines(text){return String(text||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean)}
function htmlLine(text){return esc(text).replace(/\n/g,'<br>')}
function coverPage(t){const src=getCover(t),title=t.title?.trim()||`${t.destination||'Your destination'}, thoughtfully planned`,brand=model.agency;return `<section class="p-cover"><div class="p-cover-top ${src?'':'p-no-cover'}">${src?`<img class="p-cover-photo" src="${a(src)}" alt="Destination cover">`:`<div class="placeholder-dest">${esc(t.destination||'Your next journey')}</div>`}<div class="p-cover-shade"></div><div class="p-cover-badge">${pLogo()}<em>PERSONALISED TRAVEL</em></div><span class="p-cover-index">AL BAHAR / PRIVATE JOURNEY</span></div><div class="p-cover-bottom"><div><div class="p-cover-kicker">YOUR JOURNEY BEGINS HERE</div><h1 class="p-cover-title">${esc(title)}</h1><div class="p-cover-subtitle">${esc(t.destination)} &nbsp;·&nbsp; ${esc(dateLabel(t.startDate))} — ${esc(dateLabel(t.endDate))}</div></div><div class="p-cover-foot"><div><small>PREPARED EXCLUSIVELY FOR</small><b>${esc(t.customer||'Your traveller')}</b></div><div><small>PREPARED BY</small><b>${esc(brand.staffName||brand.name)}</b></div><div style="text-align:right"><small>ITINERARY REFERENCE</small><b>${esc(t.reference)}</b></div></div></div></section>`;}
function summaryPage(t){const brand=model.agency,g=t.days.length;return `<section class="p-page">${pMast('YOUR JOURNEY')}<div class="p-kicker">THE JOURNEY / AT A GLANCE</div><h2 class="p-h1">A little more than<br>just a holiday.</h2><p class="p-lede">Prepared for ${esc(t.customer||'your traveller')}. Here is the day-by-day route and the arrangements proposed for your ${esc(t.destination||'upcoming')} journey.</p><div class="p-metrics"><div class="p-metric"><b>${g}</b><small>Travel days</small></div><div class="p-metric"><b>${Math.max(0,g-1)}</b><small>Nights</small></div><div class="p-metric"><b>${t.adults+t.children}</b><small>Travellers</small></div><div class="p-metric"><b>${t.rooms||'—'}</b><small>Rooms</small></div></div><h3 class="p-section-heading">Your route, simply.</h3>${t.days.map((d,i)=>`<div class="p-journey-line"><strong>DAY ${String(i+1).padStart(2,'0')}</strong><div>${esc(d.title||'Day '+(i+1))}<small>${esc(shortDate(plus(t.startDate,i)))} · ${esc(d.events.map(e=>e.name).filter(Boolean).slice(0,3).join(' · ')||'Details to be finalised')}</small></div></div>`).join('')}${t.stays.length?`<div class="p-stays"><h3 class="p-section-heading">Your accommodation</h3>${t.stays.map(h=>`<div class="p-stay"><div><strong>${esc(h.name)}</strong><p>${esc(h.city)} · ${esc(h.room||'Room details to confirm')} ${h.board?' · '+esc(h.board):''}</p></div><span>${esc(shortDate(h.checkIn))} – ${esc(shortDate(h.checkOut))}</span></div>`).join('')}</div>`:''}<div class="p-footerline"><span>PREPARED BY ${esc(brand.staffName||brand.name)}</span><span>${esc(t.reference)}</span></div></section>`;}
function planPages(t){
 const brand=model.agency,n=t.days.length,pages=Math.ceil(n/3);
 const base=Math.floor(n/pages),remainder=n%pages;
 let offset=0,html='';
 for(let pageIndex=0;pageIndex<pages;pageIndex++){
   const take=base+(pageIndex<remainder?1:0),slice=t.days.slice(offset,offset+take);
   html+=`<section class="p-plan-page">${pMast('DAY-BY-DAY PLAN')}<div class="p-plan-heading"><strong>The days ahead.</strong><span>${esc(t.destination.toUpperCase())} / ${t.days.length} DAYS</span></div>`;
   slice.forEach((d,j)=>{const i=offset+j,date=plus(t.startDate,i),hotel=t.stays.find(h=>date>=h.checkIn&&date<h.checkOut)?.name||d.overnight;
    html+=`<article class="p-day"><div class="p-day-head"><div class="p-day-no">${String(i+1).padStart(2,'0')}<small>${esc(shortDate(date).toUpperCase())}</small></div><div><h3>${esc(d.title||'Day '+(i+1))}</h3>${d.overview?`<p>${esc(d.overview)}</p>`:''}</div></div>${d.events.filter(e=>e.name.trim()).map(e=>`<div class="p-event"><span class="p-event-time">${esc(e.time||e.kind)}</span><div class="p-event-content"><strong>${esc(e.name)}</strong>${e.time?` <span class="p-event-kind">· ${esc(e.kind)}</span>`:''}${e.note?`<p>${esc(e.note)}</p>`:''}</div></div>`).join('')}${(!d.events.some(e=>e.name.trim()))?`<div class="p-event"><span class="p-event-time">TO PLAN</span><div class="p-event-content"><strong>Details to be confirmed</strong></div></div>`:''}${d.meals.length||hotel?`<div class="p-day-foot">${d.meals.length?`<span>MEALS · ${esc(d.meals.join(' / '))}</span>`:''}${hotel?`<span>OVERNIGHT · ${esc(hotel)}</span>`:''}</div>`:''}</article>`;
   });
   offset+=take;
   if(pageIndex===pages-1){
      if(t.included||t.excluded||t.notes){html+=`<section class="p-notes"><div class="p-notes-grid">${t.included?`<div><h3>What's included</h3>${lines(t.included).map(x=>`<p>• ${esc(x)}</p>`).join('')}</div>`:''}${t.excluded?`<div><h3>Good to know</h3>${lines(t.excluded).map(x=>`<p>• ${esc(x)}</p>`).join('')}</div>`:''}</div>${t.notes?`<div style="margin-top:7mm"><h3>Travel notes</h3><p>${htmlLine(t.notes)}</p></div>`:''}</section>`;}
      html+=`<div class="p-closer">${esc(STUB)}<br><br>PREPARED BY ${esc(brand.staffName||brand.name)}${brand.staffPhone?' · '+esc(brand.staffPhone):''}${brand.staffEmail?' · '+esc(brand.staffEmail):''}</div>`;
   }else html+=`<div class="p-closer">AL BAHAR TOURS & TRAVELS · JOURNEY CONTINUES / ${esc(t.reference)}</div>`;
   html+='</section>';
 }
 return html;
}
function printPDF(){const t=current();if(!t.customer.trim()){if(!confirm('Customer name is blank. Export this draft anyway?'))return;}if(!t.destination.trim()){toast('Enter a destination before exporting.');return;}const print=$('#printRoot');print.innerHTML=`<div class="p-doc">${coverPage(t)}${summaryPage(t)}${planPages(t)}</div>`;const images=$$('img',print);Promise.all(images.map(im=>im.complete?Promise.resolve():new Promise(r=>{im.onload=r;im.onerror=r;setTimeout(r,3000)}))).finally(()=>setTimeout(()=>window.print(),130));}
function handler(event){let btn=event.target.closest('[data-act],[data-view]');if(!btn)return;const act=btn.dataset.act,view=btn.dataset.view,n=+(btn.dataset.n||0),id=btn.dataset.id,e=+(btn.dataset.e||0);if(view){ui.view=view;ui.previewMobile=false;$('#rail').classList.remove('open');render();return;}if(act==='home'){event.preventDefault();ui.view='workspace';render();return;}if(act==='toggle-menu'){ $('#rail').classList.toggle('open');return;}
if(act==='new-trip')return newTrip();if(act==='open-trip'){model.activeId=id;ui.view='workspace';ui.dayOpen=0;save();return render();}if(act==='duplicate-trip')return makeDuplicate(current());if(act==='duplicate-selected')return makeDuplicate(model.trips.find(t=>t.id===id));
if(act==='delete-trip'){if(model.trips.length<2)return toast('Keep at least one itinerary.');return confirmBox('Delete this itinerary?','This removes it from this browser. Export a backup first if you need it.','Delete',()=>{model.trips=model.trips.filter(t=>t.id!==id);if(model.activeId===id)model.activeId=model.trips[0].id;save();render();});}
if(act==='apply-master')return useMaster(findMaster(id),false);if(act==='use-master-new')return useMaster(findMaster(id),true);if(act==='save-master')return saveMaster();if(act==='confirm-save-master')return saveMasterNow();if(act==='delete-master')return confirmBox('Delete saved master?','The master is removed. Existing customer itineraries will not be affected.','Delete',()=>{model.masters=model.masters.filter(m=>m.id!==id);save();render();});
if(act==='toggle-day'){ui.dayOpen=ui.dayOpen===n?-1:n;return render();}if(act==='add-day'){if(current().days.length>=45)return toast('Maximum 45 days.');current().days.push(dDay(`Day ${current().days.length+1}`));current().endDate=plus(current().startDate,current().days.length-1);ui.dayOpen=current().days.length-1;save();return render();}
if(act==='duplicate-day'){event.stopPropagation();const t=current();if(t.days.length>=45)return toast('Maximum 45 days.');const d=clone(t.days[n]);d.id=uid();d.events.forEach(x=>x.id=uid());t.days.splice(n+1,0,d);t.endDate=plus(t.startDate,t.days.length-1);ui.dayOpen=n+1;save();return render();}
if(act==='remove-day'){event.stopPropagation();if(current().days.length<=1)return toast('Keep at least one day.');return confirmBox('Remove day?','This removes the day and its activities from the current itinerary.','Remove day',()=>{current().days.splice(n,1);current().endDate=plus(current().startDate,current().days.length-1);ui.dayOpen=Math.max(0,Math.min(n,current().days.length-1));save();render();});}
if(act==='add-event'){const d=current().days[n];if(d.events.length>=50)return toast('Maximum 50 services per day.');d.events.push({id:uid(),name:'',kind:'Activity',time:'',note:''});ui.dayOpen=n;save();return render();}if(act==='remove-event'){current().days[n].events.splice(e,1);save();return render();}if(act==='meal'){const list=current().days[n].meals,meal=btn.dataset.meal,ix=list.indexOf(meal);ix<0?list.push(meal):list.splice(ix,1);save();return render();}
if(act==='paste-outline')return pasteDialog();if(act==='add-many')return pasteDialog(n);if(act==='apply-outline')return applyOutline(+(btn.dataset.n||-1));if(act==='add-stay')return addStay();if(act==='edit-stay')return addStay(n);if(act==='remove-stay')return confirmBox('Remove hotel stay?','The hotel will disappear from the itinerary.', 'Remove hotel',()=>{current().stays.splice(n,1);save();render()});if(act==='confirm-stay')return saveStay(+btn.dataset.n);
if(act==='edit-cover')return coverDialog();if(act==='select-image'){current().cover=btn.dataset.src;$$('.image-choice').forEach(el=>el.classList.toggle('active',el.dataset.src===btn.dataset.src));save();previewBrief();return;}if(act==='upload-cover')return $('#coverUpload').click();if(act==='no-cover'){current().cover='none';save();toast('A simple typographic cover will be used.');return;}if(act==='confirm-cover')return updateCoverData();
if(act==='open-preview'||act==='preview-full')return previewFull();if(act==='print-pdf')return printPDF();if(act==='close-dialog')return closeModal();if(act==='mobile-preview'){ui.previewMobile=true;return render();}if(act==='mobile-edit'){ui.previewMobile=false;return render();}
if(act==='save-key'){const key=$('[data-bind="_googleKey"]')?.value.trim();if(key)storage.setItem(GOOGLE_KEY,key);else storage.removeItem(GOOGLE_KEY);return toast('Browser API key updated. Restrict it to your domain and enabled APIs.');}if(act==='clear-key'){storage.removeItem(GOOGLE_KEY);render();return toast('Google API key removed.');}if(act==='google-search')return initGoogle();
if(act==='backup-all')return downloadJSON('al-bahar-journey-desk-backup.json',{schema:2,...model,settings:{}});if(act==='import-json')return $('#jsonInput').click();}
function bindHandler(event){const el=event.target;if(!el.matches('[data-bind]'))return;const path=el.dataset.bind,val=el.value; if(path==='_search'){ui.search=val;const pos=el.selectionStart;render();const fresh=$('[data-bind="_search"]');fresh.focus();fresh.setSelectionRange(pos,pos);return;}
if(path.startsWith('_'))return;if(path==='agency.logo')return;let obj=path.startsWith('agency.')?model:current();let value=(['adults','children','rooms'].includes(path))?Math.max(0,Math.min(250,Number(val)||0)):val;try{setPath(obj,path,value)}catch(e){console.warn('Invalid update',path);return;}if(path==='destination'){current().cover='';}
if(path==='startDate'&&fromISO(val))current().endDate=plus(val,current().days.length-1);
current().updatedAt=new Date().toISOString();save();if(path==='customer'||path==='destination'||path==='title')previewBrief();}
function changed(event){const el=event.target;if(!el.matches('[data-bind]'))return;let path=el.dataset.bind;if(path==='startDate'||path==='endDate'){const t=current();if(!fromISO(t.startDate)||!fromISO(t.endDate)||daysBetween(t.startDate,t.endDate)<1||daysBetween(t.startDate,t.endDate)>45){toast('Use valid travel dates, with a trip of 1–45 days.');return;}nDaysChange(t);save();render();}else if(path==='destination'){render();}else if(path.startsWith('days.')){save();render();}}
function onImport(event){const f=event.target.files?.[0];if(!f)return;f.text().then(text=>{const data=JSON.parse(text);if(data?.schema===2&&data.trips?.length){const trips=data.trips.map(normalizeTrip).filter(Boolean);confirmBox('Import backup?','This will replace the current V2 local drafts and master templates. Back up first if needed.','Import backup',()=>{model={...model,...data,trips};model.activeId=trips[0].id;save();ui.view='trips';render();toast('V2 backup imported.');});}else if(data?.trips?.length){const trips=data.trips.map(convertLegacy).filter(Boolean);model.trips.push(...trips);save();ui.view='trips';render();toast(`${trips.length} V1.3 itinerary drafts imported.`);}else if(data?.days?.length){const t=convertLegacy(data);model.trips.push(t);save();ui.view='trips';render();toast('Itinerary imported.');}else throw Error('Unsupported backup structure.');}).catch(e=>toast('Could not read file: '+e.message)).finally(()=>event.target.value='');}
function onCover(event){const f=event.target.files?.[0];if(!f)return;if(f.size>1.2*1024*1024)return toast('Use a cover under 1.2 MB for reliable browser storage.');const reader=new FileReader();reader.onload=()=>{current().cover=reader.result;save();closeModal();render();toast('Cover applied. It will appear in exported PDFs.');};reader.readAsDataURL(f);event.target.value='';}
function init(){load();render();document.addEventListener('click',handler);document.addEventListener('input',bindHandler);document.addEventListener('change',changed);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if((e.key==='Enter'||e.key===' ')&&e.target.matches('.day-main')){e.preventDefault();e.target.click();}});$('#dialogBackdrop').addEventListener('click',e=>{if(e.target.id==='dialogBackdrop')closeModal();});$('#jsonInput').addEventListener('change',onImport);$('#coverUpload').addEventListener('change',onCover);}
document.readyState==='loading'?document.addEventListener('DOMContentLoaded',init):init();
})();
